solution:
struct Counter {
    value: i32,
}

impl Counter {
    fn new() -> Counter {
        Counter { value: 0 }
    }

    fn increment(&mut self) {
        self.value += 1;
    }

    fn add(&mut self, amount: i32) {
        self.value += amount;
    }

    fn get(&self) -> i32 {
        self.value
    }
}
